        static void Begin(bool restart){string config=Environment.GetEnvironmentVariable("HOTR_BACKEND_VERIFICATION_CONFIG");if(string.IsNullOrEmpty(config))throw new InvalidOperationException("Explicit backend fixture required");string marker=Path.Combine(Path.GetDirectoryName(config),"ui-run-id.txt");string id=restart?File.ReadAllText(marker):Guid.NewGuid().ToString("N");Guid parsed;if(!Guid.TryParseExact(id,"N",out parsed))throw new InvalidOperationException("Invalid UI run ID");if(!restart)File.WriteAllText(marker,id);SessionState.SetBool(Key,true);SessionState.SetString(Key+".id",id);SessionState.SetString(Key+".mode",restart?"Restart":"Play");EditorSceneManager.OpenScene("Assets/HeartOfTheRain/App/FirstStart/Scenes/M65_First_Start.unity");Portrait(restart?320:900,restart?568:1600);Directory.CreateDirectory(Application.persistentDataPath);File.WriteAllText(Path.Combine(Application.persistentDataPath,BackendGiftUIProbe.RequestName),JsonUtility.ToJson(new BackendGiftUIProbe.Request{runId=id,mode=restart?"Restart":"Play"}));EditorApplication.isPlaying=true;}
        static void Portrait(int width,int height){
            var assembly=typeof(Editor).Assembly;var sizes=assembly.GetType("UnityEditor.GameViewSizes");var singleton=typeof(ScriptableSingleton<>).MakeGenericType(sizes).GetProperty("instance",BindingFlags.Public|BindingFlags.Static).GetValue(null);string groupName=EditorUserBuildSettings.activeBuildTarget==BuildTarget.Android?"Android":EditorUserBuildSettings.activeBuildTarget==BuildTarget.iOS?"iOS":"Standalone";SessionState.SetString(Key+".group",groupName);var group=sizes.GetMethod("GetGroup").Invoke(singleton,new[]{Enum.Parse(assembly.GetType("UnityEditor.GameViewSizeGroupType"),groupName)});
            var view=EditorWindow.GetWindow(assembly.GetType("UnityEditor.GameView"));var selected=view.GetType().GetProperty("selectedSizeIndex",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance);SessionState.SetInt(Key+".previous",(int)selected.GetValue(view));int count=(int)group.GetType().GetMethod("GetTotalCount").Invoke(group,null);SessionState.SetInt(Key+".added",count);var size=Activator.CreateInstance(assembly.GetType("UnityEditor.GameViewSize"),BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,new object[]{Enum.Parse(assembly.GetType("UnityEditor.GameViewSizeType"),"FixedResolution"),width,height,"HOTR backend gift UI"},null);group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{size});selected.SetValue(view,count);
        }
