            var sizes=assembly.GetType("UnityEditor.GameViewSizes");var singleton=typeof(ScriptableSingleton<>).MakeGenericType(sizes).GetProperty("instance",BindingFlags.Public|BindingFlags.Static).GetValue(null);var group=sizes.GetMethod("GetGroup").Invoke(singleton,new[]{Enum.Parse(assembly.GetType("UnityEditor.GameViewSizeGroupType"),SessionState.GetString(Key+".group","Standalone"))});try{group.GetType().GetMethod("RemoveCustomSize").Invoke(group,new object[]{SessionState.GetInt(Key+".added",0)});}catch(TargetInvocationException){}SessionState.EraseInt(Key+".previous");SessionState.EraseInt(Key+".added");SessionState.EraseString(Key+".group");
        }
