                string output=Path.GetFullPath("../Verification/Evidence/BackendGiftUI");Directory.CreateDirectory(output);string root=Path.GetFullPath("../.verification-cache/BackendGiftUI/U-"+SessionState.GetString(Key+".id","").Substring(0,8));File.Copy(Path.Combine(root,"Report.json"),Path.Combine(output,SessionState.GetString(Key+".mode","")=="Restart"?"Native_Restart_Checks.json":"Native_Play_Checks.json"),true);foreach(string frame in probe.report.frames)File.Copy(Path.Combine(root,frame),Path.Combine(output,frame),true);Finish(probe.report.failures.Count==0?0:1);
            }else if(EditorApplication.timeSinceStartup-started>200){Debug.LogError("Backend Daily Gift UI verification timed out");Finish(1);}}
