        [Serializable] sealed class LayoutReport {public string utc,status,unity,scope="Native Unity layout/font/glyph and component-state checks. No Android, input or native-language editorial approval.";public int checks;public string[] failures;}
        public static void Checks(){
            var report=new LayoutReport{utc=DateTime.UtcNow.ToString("o"),unity=Application.unityVersion,failures=new string[0]};int locale=GameLocale.Current;GameObject go=null;
            try{
                Action<bool,string> check=(ok,name)=>{report.checks++;if(!ok)throw new InvalidOperationException(name);};var assets=AssetDatabase.LoadAssetAtPath<PreLevelAssets>("Assets/HeartOfTheRain/App/PreLevel/PreLevelAssets.asset");go=new GameObject("Backend gift font verification",typeof(RectTransform),typeof(Text));var text=go.GetComponent<Text>();text.font=assets.home.boldFont;text.verticalOverflow=VerticalWrapMode.Truncate;text.supportRichText=false;
                for(int language=0;language<5;language++){GameLocale.Select(language);foreach(int width in new[]{320,393,768})for(int state=0;state<7;state++){
                    var view=new DailyGiftView{schedule=GiftSchedule.Preview(),development=true,loading=state==0||state==1,claiming=state==1,pending=state==3,networkError=state==2||state==3,received=state==5};if(state>=3)view.offer=new GiftOffer{step=6,claimed=state>=5,grant=GiftSchedule.Preview().days[6]};if(state==6)view.error=true;var frame=DailyGiftLayout.Build(width,568,view);var panel=frame.elements.First(e=>e.id=="panel");
                    check(frame.elements.First(e=>e.id=="claim").action==(view.loading?"disabled":state==5?"close":"claim"),"Primary action matches network/model state");check(frame.elements.Any(e=>e.id=="close")!=view.error,"Only fatal save errors suppress close");
                    // Every element under the panel (the R1 frame nests header/viewport/body/footer), measured as DailyGiftPage renders it: design title/body font, wrapped, shrunk to the row. Scroll-body rows may run past the panel height.
                    var design=DailyGiftDesignAssets.Load();var byId=frame.elements.ToDictionary(e=>e.id);
                    foreach(var e in frame.elements){if(e.id=="panel")continue;float ax=e.x,ay=e.y;bool inPanel=false,scrolls=e.id=="body";for(var p=e;!string.IsNullOrEmpty(p.parent)&&byId.TryGetValue(p.parent,out p);){if(p.id=="panel"){inPanel=true;break;}if(p.id=="body")scrolls=true;ax+=p.x;ay+=p.y;}if(!inPanel)continue;
                        // The round close button straddles the panel corner by design.
                        bool overhang=e.id=="close"||e.parent=="close";
                        check(overhang||ax>=-.01f&&ax+e.width<=panel.width+.01f&&(scrolls||ay>=-.01f&&ay+e.height<=panel.height+.01f),"Element stays inside approved shell: "+e.id);if(e.kind=="sprite")check(design.Find(e.asset)!=null,"Approved asset exists: "+e.asset);if(e.kind!="text")continue;
                        bool title=e.id=="title"||e.id.Contains("label")||e.id.Contains("quantity")||e.id.Contains("heading");text.font=title?design.titleFont:design.bodyFont;text.text=e.text;text.fontSize=e.fontSize;text.horizontalOverflow=HorizontalWrapMode.Wrap;text.rectTransform.sizeDelta=new Vector2(e.width,e.height);while(text.preferredHeight>e.height+.1f&&text.fontSize>10)text.fontSize--;text.font.RequestCharactersInTexture(text.text,text.fontSize);
                        check(text.preferredHeight<=e.height+.5f,"Localized native text fits: "+e.id);check(e.text.All(c=>char.IsWhiteSpace(c)||text.font.HasCharacter(c)),"Native glyphs available: "+e.id);}
                }}
                var hostObject=new GameObject("Unconfigured backend host guard");try{var host=hostObject.AddComponent<PlayerProfileHost>();host.VerificationBackendClient=new BackendClient("http://127.0.0.1/",new string('x',43),true);bool rejected=false;try{host.Initialize(null,null);}catch(InvalidOperationException){rejected=true;}check(rejected&&host.Service==null,"Remote review cannot initialize an ordinary repository");}finally{UnityEngine.Object.DestroyImmediate(hostObject);}
            }catch(Exception e){report.failures=new[]{e.ToString()};}finally{GameLocale.Select(locale);if(go)UnityEngine.Object.DestroyImmediate(go);}
